          d="m -407.76429,287.10417 c 2.60306,2.66671 6.51652,4.19793 10.74677,4.19793 3.08713,0 6.12884,-0.82044 8.66322,-2.30757 0.33009,0.0355 0.66462,0.0667 1.02572,0.0667 h 115.89063 c 4.03974,0 7.5788,-1.36885 10.47651,-4.1818 l 0.42978,-0.43333 c 2.6662,-2.57639 4.07186,-6.00655 4.07186,-9.92812 v -98.78123 c 0,-5.64633 -2.75704,-9.02489 -5.16958,-10.89266 -1.92516,-2.34305 -5.39997,-5.01836 -11.22087,-5.01836 h -121.54094 c -4.81733,0 -8.93017,1.92153 -11.57422,5.40009 -2.82903,3.73339 -3.70632,8.90982 -2.32282,13.60453 -0.14954,32.89517 -1.14313,65.96131 -2.95531,98.28122 -0.22154,3.97855 0.9803,7.43131 3.47925,9.99264 z"
